# nt300 build
def buildmany(nt):
 random.seed(9000+nt);n=32;H=nx.DiGraph();H.add_nodes_from(range(n));loads={};roots={i:0 for i in range(n)}
 for k in range(nt):
  T=[]
  for v in range(1,n):T.append((random.randrange(v),v))
  root=random.randrange(n);w=random.randint(1,10);adj={i:[] for i in range(n)}
  for a,b in T:adj[a].append(b);adj[b].append(a)
  st=[root];seen={root}
  while st:
   x=st.pop()
   for y in adj[x]:
    if y not in seen:seen.add(y);loads[(x,y)]=loads.get((x,y),0)+w;st.append(y)
  roots[root]+=w
 for (a,b),c in loads.items():H.add_edge(a,b,capacity=c)
 return H,roots
H,roots=buildmany(300);t=time.time();Ts,Cs=fastgen_prvar.fast_generate(H,list(range(32)),roots);print('many300 pr',time.time()-t,len(Ts))
